const payload = $json.body || $json;

if (
  !payload.project_id ||
  typeof payload.project_id !== 'string' ||
  payload.project_id.trim() === ''
) {
  throw new Error(
    "Validation Error: 'project_id' is required and must be a valid non-empty string."
  );
}

if (
  !payload.text_content ||
  typeof payload.text_content !== 'string' ||
  payload.text_content.trim() === ''
) {
  throw new Error(
    "Validation Error: 'text_content' is required and cannot be empty."
  );
}

const sanitized = {
  project_id: payload.project_id.trim(),
  text_content: payload.text_content.trim(),
  filename:
    payload.filename &&
    typeof payload.filename === 'string' &&
    payload.filename.trim()
      ? payload.filename.trim()
      : 'daily_report.txt',
  source_type:
    payload.source_type &&
    typeof payload.source_type === 'string' &&
    payload.source_type.trim()
      ? payload.source_type.trim()
      : 'text',
  uploaded_by: payload.uploaded_by || null,
  received_at: new Date().toISOString()
};

return [{ json: sanitized }];

const rawOutput = $json.output ?? $json.text ?? $json.response?.output ?? $json.response?.text ?? "";

const originalText = $('Validate & Sanitize Input').first().json.text_content;
const projectId = $('Validate & Sanitize Input').first().json.project_id;

let parsed;

try {
  // Structured Output Parser may already return an object
  if (typeof rawOutput === "object" && rawOutput !== null) {
    parsed = rawOutput;
  } else {
    let cleaned = String(rawOutput).trim();

    if (cleaned.startsWith("```json")) {
      cleaned = cleaned.replace(/^```json/, "").replace(/```$/, "").trim();
    } else if (cleaned.startsWith("```")) {
      cleaned = cleaned.replace(/^```/, "").replace(/```$/, "").trim();
    }

    parsed = JSON.parse(cleaned);
  }
} catch (err) {
  throw new Error(
    `AI Extraction Error: Failed to parse LLM output as JSON. Raw output: ${JSON.stringify(rawOutput)}`
  );
}

if (!parsed || typeof parsed !== 'object' || Array.isArray(parsed) || !Array.isArray(parsed.events)) {
  throw new Error(
    "AI Extraction Error: Model output must be an object containing a root 'events' array."
  );
}

const ALLOWED_EVENT_TYPES = [
  "STARTED",
  "IN_PROGRESS",
  "COMPLETED",
  "ON_HOLD",
  "BLOCKED",
  "CANCELLED"
];

const ALLOWED_DISCIPLINES = [
  "Civil",
  "Piping",
  "Mechanical",
  "Electrical",
  "Instrumentation",
  "HSE"
];

const DATE_REGEX = /^\d{4}-(0[1-9]|1[0-2])-(0[1-9]|[12]\d|3[01])$/;
const TIME_REGEX = /^([01]\d|2[0-3]):[0-5]\d$/;

const validatedEvents = parsed.events.map((evt, idx) => {

  if (
    !evt.activity_description ||
    typeof evt.activity_description !== 'string' ||
    evt.activity_description.trim() === ''
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'activity_description' is required and must be a non-empty string.`
    );
  }

  if (
    !evt.event_type ||
    !ALLOWED_EVENT_TYPES.includes(evt.event_type)
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: Invalid 'event_type' ('${evt.event_type}'). Allowed: ${ALLOWED_EVENT_TYPES.join(', ')}.`
    );
  }

  if (
    !evt.source_evidence ||
    typeof evt.source_evidence !== 'string' ||
    evt.source_evidence.trim() === ''
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'source_evidence' is required and must be a non-empty string.`
    );
  }

  if (!originalText.includes(evt.source_evidence)) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'source_evidence' is not an exact verbatim substring of the input text.`
    );
  }

  if (
    evt.discipline !== null &&
    !ALLOWED_DISCIPLINES.includes(evt.discipline)
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: Invalid 'discipline' ('${evt.discipline}'). Allowed: ${ALLOWED_DISCIPLINES.join(', ')} or null.`
    );
  }

  if (evt.event_date !== null) {
    if (
      typeof evt.event_date !== 'string' ||
      !DATE_REGEX.test(evt.event_date)
    ) {
      throw new Error(
        `Validation Error [Event ${idx}]: Invalid 'event_date' ('${evt.event_date}'). Must be format 'YYYY-MM-DD' or null.`
      );
    }
  }

  if (evt.event_time !== null) {
    if (
      typeof evt.event_time !== 'string' ||
      !TIME_REGEX.test(evt.event_time)
    ) {
      throw new Error(
        `Validation Error [Event ${idx}]: Invalid 'event_time' ('${evt.event_time}'). Must be 24-hour format 'HH:MM' or null.`
      );
    }
  }

  if (
    evt.asset !== null &&
    (typeof evt.asset !== 'string' || evt.asset.trim() === '')
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'asset' must be a valid string or null.`
    );
  }

  if (
    evt.location !== null &&
    (typeof evt.location !== 'string' || evt.location.trim() === '')
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'location' must be a valid string or null.`
    );
  }

  if (
    evt.quantity !== null &&
    (typeof evt.quantity !== 'string' || evt.quantity.trim() === '')
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'quantity' must be a valid string or null.`
    );
  }

  if (
    evt.delay_reason !== null &&
    (typeof evt.delay_reason !== 'string' || evt.delay_reason.trim() === '')
  ) {
    throw new Error(
      `Validation Error [Event ${idx}]: 'delay_reason' must be a valid string or null.`
    );
  }

  return {
    document_id: null,
    project_id: projectId,
    discipline: evt.discipline,
    activity_description: evt.activity_description.trim(),
    asset: evt.asset ? evt.asset.trim() : null,
    location: evt.location ? evt.location.trim() : null,
    event_type: evt.event_type,
    event_date: evt.event_date,
    event_time: evt.event_time,
    quantity: evt.quantity ? evt.quantity.trim() : null,
    delay_reason: evt.delay_reason ? evt.delay_reason.trim() : null,
    source_evidence: evt.source_evidence
  };
});

return [
  {
    json: {
      project_id: projectId,
      events_count: validatedEvents.length,
      events: validatedEvents
    }
  }
];

const inputMeta = $('Validate & Sanitize Input').first().json;
const eventsData = $('Parse & Validate Events').first().json;

return [{
  json: {
    success: true,
    status: "EXTRACTED_UNSAVED",
    message: "AI extraction successful. Database persistence is pending Member 2 schema finalization.",
    data: {
      project_id: inputMeta.project_id,
      filename: inputMeta.filename,
      source_type: inputMeta.source_type,
      events_count: eventsData.events_count,
      events: eventsData.events
    }
  }
}];

